-- Client Portal database schema (PostgreSQL 16+).
-- Generated by `python -m app.cli schema-sql` from app/db.py. The app also creates these tables on first start.

CREATE TABLE activity_events (
	seq BIGSERIAL NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	at TIMESTAMP WITH TIME ZONE NOT NULL, 
	action VARCHAR(60) NOT NULL, 
	actor_user_id VARCHAR(36), 
	actor_email VARCHAR(254), 
	actor_name VARCHAR(120), 
	actor_role VARCHAR(16), 
	target JSONB, 
	details JSONB, 
	ip VARCHAR(64), 
	user_agent VARCHAR(200), 
	content_hash VARCHAR(64) NOT NULL, 
	prev_hash VARCHAR(64), 
	hash VARCHAR(64) NOT NULL, 
	redacted_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (seq), 
	UNIQUE (id)
);

CREATE INDEX ix_activity_events_action ON activity_events (action);
CREATE INDEX ix_activity_events_actor_user_id ON activity_events (actor_user_id);
CREATE INDEX ix_activity_events_at ON activity_events (at);
CREATE INDEX ix_activity_target_user ON activity_events (actor_user_id, at);

CREATE TABLE users (
	id VARCHAR(36) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	name VARCHAR(120), 
	phone VARCHAR(40), 
	zoho_contact_id VARCHAR(40), 
	zoho_lead_id VARCHAR(40), 
	must_change_password BOOLEAN NOT NULL, 
	session_version INTEGER NOT NULL, 
	email_verified_at TIMESTAMP WITH TIME ZONE, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	converted_at TIMESTAMP WITH TIME ZONE, 
	created_by VARCHAR(36), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_users_role CHECK (role IN ('admin', 'client', 'guest')), 
	CONSTRAINT ck_users_status CHECK (status IN ('active', 'disabled', 'erased')), 
	CONSTRAINT ck_users_client_contact CHECK (role <> 'client' OR zoho_contact_id IS NOT NULL OR status = 'erased'), 
	UNIQUE (zoho_contact_id), 
	FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_users_role ON users (role);

CREATE TABLE consents (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	kind VARCHAR(40) NOT NULL, 
	policy_version VARCHAR(40) NOT NULL, 
	granted_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	withdrawn_at TIMESTAMP WITH TIME ZONE, 
	ip VARCHAR(64), 
	user_agent VARCHAR(200), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_consents_user_id ON consents (user_id);

CREATE TABLE otp_challenges (
	id VARCHAR(36) NOT NULL, 
	purpose VARCHAR(20) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	user_id VARCHAR(36), 
	code_hash VARCHAR(128) NOT NULL, 
	payload JSONB, 
	attempts INTEGER NOT NULL, 
	resends INTEGER NOT NULL, 
	last_sent_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	consumed_at TIMESTAMP WITH TIME ZONE, 
	ip VARCHAR(64), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_otp_purpose CHECK (purpose IN ('login', 'signup', 'password_reset')), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_otp_challenges_email ON otp_challenges (email);
CREATE INDEX ix_otp_challenges_expires_at ON otp_challenges (expires_at);

-- The audit trail is append-only. Run the app as a role that cannot UPDATE or DELETE it
-- except through the erasure and retention jobs, e.g.:
--   REVOKE UPDATE, DELETE ON activity_events FROM portal_app;
--   GRANT UPDATE (actor_email, actor_name, ip, user_agent, details, redacted_at), DELETE ON activity_events TO portal_app;
